      "rationale": "Change only the GRU reset gate to 0.1 + 0.9 * sigmoid(a_r), preserving the update gate, candidate equation, parameter shapes, initialization, embeddings, readout, scoring, loss and optimizer. Precompute input projections and script the recurrent loop. The embedded predictor already imports GRU4RecModel from train.py, so it loads the same modified architecture and one checkpoint per category.",
      "edits": [
        {
          "find": "class GRU4RecModel(nn.Module):",
          "replace": "@torch.jit.script
def _reset_floor_gru_layer(inputs: torch.Tensor, hidden: torch.Tensor,
                          weight_ih: torch.Tensor, weight_hh: torch.Tensor,
                          bias_ih: torch.Tensor, bias_hh: torch.Tensor):
    input_gates = torch.nn.functional.linear(inputs, weight_ih, bias_ih)
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    for step in range(inputs.size(1)):
        input_reset, input_update, input_new = input_gates[:, step].chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_new = torch.nn.functional.linear(
            hidden, weight_hh, bias_hh
        ).chunk(3, dim=-1)
        reset = 0.1 + 0.9 * torch.sigmoid(input_reset + hidden_reset)
        update = torch.sigmoid(input_update + hidden_update)
        candidate = torch.tanh(input_new + reset * hidden_new)
        hidden = candidate + update * (hidden - candidate)
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class ResetFloorGRU(nn.GRU):
    def forward(self, inputs: torch.Tensor, hx: torch.Tensor | None = None):
        if not self.batch_first:
            inputs = inputs.transpose(0, 1)
        if hx is None:
            hx = inputs.new_zeros(self.num_layers, inputs.size(0), self.hidden_size)
        out = inputs
        final_states = []
        for layer in range(self.num_layers):
            out, hidden = _reset_floor_gru_layer(
                out, hx[layer],
                getattr(self, f'weight_ih_l{layer}'),
                getattr(self, f'weight_hh_l{layer}'),
                getattr(self, f'bias_ih_l{layer}'),
                getattr(self, f'bias_hh_l{layer}'),
            )
            final_states.append(hidden)
            if layer < self.num_layers - 1 and self.dropout > 0.0:
                out = torch.nn.functional.dropout(out, p=self.dropout, training=self.training)
        if not self.batch_first:
            out = out.transpose(0, 1)
        return out, torch.stack(final_states, dim=0)


class GRU4RecModel(nn.Module):"
